/**
 * @method
 * @name goCal
 * @description go Cal 처리
 * @returns {void}
 * @hidden N
 */
scwin.goCal = function () {
    const calcURL = '/ui/jsp/JLDFIL45501.xml';
    (Promise.resolve($c.win.openPopup(calcURL, { id: "calc", scrollbars: true, resizable: true, width: "1024", height: "700", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("calc"); this.closed = true; } });
};

