    await $c.win.openPopup(searchDisclsPopURL, { id: "searchPop", scrollbars: true, width: "1024", height: "700", type: "pageFramePopup" }, { method: "searchPopDsclHistory" });
};

/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function () {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/submission/disclosure.do?method=searchDisclosureDocument", unresolved: "nav:" + "/submission/disclosure.do?method=searchDisclosureDocument" }; })();
    (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    (document.writeForm || { elements: [] }).target = 'writeDisclosure';
};

/**
 * @method
 * @name registerProcess
 * @description register Process 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWrite();
    } else {
        registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name selectDiscls
 * @description select Discls 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectDiscls = function () {
    const oName = document.getElementsByName("objNm");
    scwin.contnValue = oName.getValue();
    switchContn(scwin.contnValue, '');
};

async function selWrite() {
    const formKorNm = document.getElementsByName("formNm");
    let chkCnt = 0;
    for (let i = 0; i < formKorNm.length; i++) {
        if (formKorNm[i].checked === true) {
            scwin.contnValue = formKorNm[i].value;
            chkCnt++;
        }
    }
    if (chkCnt < 1) {
        await $c.win.alert("공시를 선택해주세요");
        return;
    } else {
        scwin.goWrite(scwin.contnValue);
    }
}

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @param {String} formKorNm formKorNm
 * @returns {void}
 * @hidden N
 */
scwin.goWrite = function (formKorNm) {
    $c.win.setPageFrameSrc(null, '/ui/jsp/JLDFIL00000.xml');
    scwin.formKorNm_val = formKorNm;
    scwin.linkGb_val = "1";
    self.setTimeout(function(){ scwin.init() }, 3000);
};

/**
 * @method
 * @name setOpener
 * @description set Opener 처리
 * @param {*} linkGb linkGb
 * @param {String} formKorNm formKorNm
 * @returns {void}
 * @hidden N
 */
scwin.setOpener = function (linkGb, formKorNm) {
    if (linkGb === "1") {
        ((scwin.opener().getComponentById("searchScope")) || { setValue: function () {} }).setValue("2");
        ((scwin.opener().getComponentById("method")) || { setValue: function () {} }).setValue("searchDisclosureForm");
        ((scwin.opener().getComponentById("tabDiv")) || { setValue: function () {} }).setValue("search");
        ((scwin.opener().getComponentById("isAllEdit")) || { setValue: function () {} }).setValue("true");
        ((scwin.opener().getComponentById("formKorNm")) || { setValue: function () {} }).setValue(formKorNm);
        formKorNm1.focus();
        opener./* 수동 전환 필요: 폼 editForm 제출 — action 미보유 */ document.editForm.submit();
    } else {
        if (linkGb === "2") {
            ((scwin.opener().getComponentById("keywordField")) || { setValue: function () {} }).setValue("1");
            ((scwin.opener().getComponentById("keyword")) || { setValue: function () {} }).setValue(formKorNm);
            keyword.focus();
            opener./* 수동 전환 필요: 폼 dsclDataForm 제출 — action 미보유 */ document.dsclDataForm.submit();
        }
    }
};

/**
 * @method
 * @name goPds
 * @description go Pds 처리
 * @returns {void}
 * @hidden N
 */
scwin.goPds = function () {
    $c.win.setPageFrameSrc(null, '/ui/jsp/JLDFIL15900.xml');
    scwin.formKorNm_val = "우회상장";
    scwin.linkGb_val = "2";
    self.setTimeout(function(){ scwin.init() }, 3000);
};

/**
 * @method
 * @name execHistory
 * @description exec History 처리
 * @param {*} contnVal contnVal
 * @returns {void}
 * @hidden N
 */
scwin.execHistory = function (contnVal) {
    scwin.history = scwin.history + "|" + contnVal;
};

function historyBack() {
    let prevId = "";
    scwin.history = scwin.history.replace(scwin.history.substring(scwin.history.lastIndexOf('|', scwin.history.length), scwin.history.length), '');
    if (scwin.history === '') {
        $c.win.setPageFrameSrc($c.win.getFrame(), null);
    } else {
        prevId = scwin.history.substring(scwin.history.lastIndexOf('|', scwin.history.length) + 1, scwin.history.length);
        switchContn(prevId, "prev");
    }
}

function switchContn(contnVal, switchGb) {
    if (switchGb === '') {
        scwin.execHistory(contnVal);
    }

    $c.util.getComponent('dma_pageContext').set('contnVal', String(contnVal));
    scwin.init_conds();

}

/**
 * @method
 * @name changeDiv
 * @description change Div 처리
 * @param {String} tabId 탭 id
 * @returns {void}
 * @hidden N
 */
scwin.changeDiv = function (tabId) {
    for (let i = 1; i <= 6; i++) {
        if (i === tabId) {
            $("#td_tab" + i).removeClass();
            $("#td_tab" + i).addClass("td_tab_2 w160");
            $("#td_tab" + i).find("span").addClass("fc-b");
        } else {
            $("#td_tab" + i).removeClass();
            $("#td_tab" + i).addClass("td_tab_1 w160");
            $("#td_tab" + i).find("span").removeClass();
        }
    }
};

/**
 * @method
 * @name changeContnArea2
 * @description change Contn Area2 처리
 * @param {String} contnId contnId
 * @returns {void}
 * @hidden N
 */
scwin.changeContnArea2 = function (contnId) {

    $c.util.getComponent('dma_pageContext').set('contnId', String(contnId));
    scwin.init_conds();

};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};
